const body = $input.first().json.body ?? {};
let payload = body.payload;
if (typeof payload === 'string') payload = JSON.parse(payload);

const action = (payload.actions || [])[0] || {};

const DECISIONS = { approve_breach: 'approved', reject_breach: 'rejected' };
const decision = DECISIONS[action.action_id];
if (!decision) {
  throw new Error(`Unsupported action_id: ${action.action_id}`);
}

const findingId = Number.parseInt(action.value, 10);
if (!Number.isInteger(findingId) || findingId <= 0) {
  throw new Error(`Missing or invalid finding_id in button value: ${action.value}`);
}

return [{
  json: {
    finding_id: findingId,
    decision,
    reviewer: payload.user?.id ?? '',
    reviewer_name: payload.user?.username ?? payload.user?.name ?? '',
    response_url: payload.response_url ?? '',
    channel: payload.channel?.id ?? '',
    message_ts: payload.message?.ts ?? '',
    original_blocks: payload.message?.blocks ?? [],
  },
}];

const parsed = $('Parse Slack action').first().json;
const status = $json.review_status;

const icon = status === 'approved' ? ':white_check_mark:' : ':x:';
const label = status === 'approved' ? 'Approved' : 'Rejected';
const by = parsed.reviewer ? ` by <@${parsed.reviewer}>` : '';

// keep the original content, drop the buttons, append the verdict
const blocks = (parsed.original_blocks || []).filter((b) => b.type !== 'actions');
blocks.push({
  type: 'section',
  text: { type: 'mrkdwn', text: `${icon} *${label}*${by}` },
});

return [{ json: { slack_body: { replace_original: true, blocks } } }];
